import sys
import heapq

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    q = int(input[ptr])
    ptr += 1
    s = int(input[ptr])
    ptr += 1

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[s] = 0

    heap = []
    heapq.heappush(heap, (0, s))

    # Store plans in a list
    plans = []
    for _ in range(q):
        t = int(input[ptr])
        ptr += 1
        if t == 1:
            v, u, w = int(input[ptr]), int(input[ptr+1]), int(input[ptr+2])
            ptr += 3
            plans.append((t, v, u, w))
        else:
            v, l, r, w = int(input[ptr]), int(input[ptr+1]), int(input[ptr+2]), int(input[ptr+3])
            ptr += 4
            plans.append((t, v, l, r, w))

    # Process each plan dynamically during Dijkstra's algorithm
    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for plan in plans:
            t = plan[0]
            if t == 1:
                v, to, w = plan[1], plan[2], plan[3]
                if v == u and dist[to] > dist[u] + w:
                    dist[to] = dist[u] + w
                    heapq.heappush(heap, (dist[to], to))
            elif t == 2:
                v, l, r, w = plan[1], plan[2], plan[3], plan[4]
                if v == u:
                    for to in range(l, r+1):
                        if dist[to] > dist[u] + w:
                            dist[to] = dist[u] + w
                            heapq.heappush(heap, (dist[to], to))
            elif t == 3:
                v, l, r, w = plan[1], plan[2], plan[3], plan[4]
                for from_planet in range(l, r+1):
                    if from_planet == u and dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        heapq.heappush(heap, (dist[v], v))

    output = []
    for i in range(1, n+1):
        if dist[i] == INF:
            output.append(-1)
        else:
            output.append(dist[i])

    print(' '.join(map(str, output)))

if __name__ == '__main__':
    main()
